<?php namespace App\Http\Resources; use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\JsonResource; class ChildResource extends JsonResource { public function toArray(Request $r):array{return ['id'=>$this->id,'code'=>$this->code,'full_name'=>$this->full_name,'saint_name'=>$this->saint_name,'date_of_birth'=>$this->date_of_birth?->toDateString(),'status'=>$this->status,'parents'=>$this->whenLoaded('parents',fn()=>$this->parents->map(fn($p)=>['id'=>$p->id,'name'=>$p->user->name,'phone'=>$p->phone]))];} }
